const body = $input.first().json.body ?? $input.first().json;

const required = ['client_id', 'supabase_url', 'service_key'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error(`Campos obrigatórios ausentes: ${missing.join(', ')}`);
}

return [{ json: {
  client_id:    body.client_id,
  client_name:  body.client_name  ?? body.client_id,
  supabase_url: body.supabase_url,
  anon_key:     body.anon_key     ?? '',
  service_key:  body.service_key,
  org_id:       body.org_id       ?? null,
  max_users:    body.max_users    ?? 3,
  plan_name:    body.plan_name    ?? 'Incluído',
} }];

const schemaResult = $input.first().json;
const input = $('Validar Payload').first().json;

const schemaOk =
  schemaResult.success === true ||
  schemaResult.applied  === true ||
  (typeof schemaResult.message === 'string' &&
   schemaResult.message.toLowerCase().includes('sucesso'));

const schemaError = schemaOk
  ? null
  : (schemaResult.error ?? `provision-client-db retornou falha`);

console.log(
  `[c8-provision] client=${input.client_id}`,
  `schema_ok=${schemaOk}`,
  schemaError ? `error=${schemaError}` : ''
);

return [{ json: {
  success:      schemaOk,
  client_id:    input.client_id,
  client_name:  input.client_name,
  schema_applied: schemaOk,
  error:        schemaError,
} }];
